function DesktopTrialNotice(){
 const [trial,setTrial]=useState<{mode:string;status?:string;expiresAt?:string;daysRemaining?:number;expired?:boolean}|null>(null);
 useEffect(()=>{if(!window.autrobDesktop?.isDesktop)return;api<{mode:string;status?:string;expiresAt?:string;daysRemaining?:number;expired?:boolean}>('/api/license/status').then(setTrial).catch(()=>setTrial(null));},[]);
 if(!window.autrobDesktop?.isDesktop||trial?.mode!=='trial')return null;
 const expires=trial.expiresAt?new Date(trial.expiresAt).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'';
 return <div className={`desktop-trial-notice${trial.expired?' expired':''}`} role="status"><span className="trial-notice-dot"/><span><strong>{trial.expired?'Free Trial ended':`Free Trial · ${trial.daysRemaining} ${trial.daysRemaining===1?'day':'days'} left`}</strong><small>{trial.expired?'Your data stays on this computer.':'Trial access ends '+expires+'.'}</small></span></div>;
}

